import requests
u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
for q in ['ID2 arsenic trioxide','"inhibitor of DNA binding 2" arsenic trioxide','ID2 arsenic trioxide cancer']:
 r=requests.get(u,params={'db':'pubmed','term':q,'retmax':20,'retmode':'json'},timeout=20)
 print('\nQUERY',q,'STATUS',r.status_code)
 j=r.json()['esearchresult']; print('COUNT',j['count'],'IDS',j['idlist'])
 if j['idlist']:
  x=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(j['idlist']),'retmode':'json'},timeout=20).json()['result']
  for pid in j['idlist']:
   z=x[pid]; print(pid,z.get('title'),z.get('pubdate'))

import requests
s=requests.Session()
for q in ['ID2 arsenic trioxide[Title/Abstract]','"inhibitor of DNA binding 2" AND arsenic trioxide','ID2 AND arsenic trioxide AND cancer']:
 r=s.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi',params={'db':'pubmed','term':q,'retmax':25,'retmode':'json'},timeout=25)
 print('\nQUERY',q,'HTTP',r.status_code,'BODY',r.text[:1000])
 try: ids=r.json().get('esearchresult',{}).get('idlist',[])
 except Exception as e: print('PARSE',e); continue
 if ids:
  t=s.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi',params={'db':'pubmed','id':','.join(ids),'rettype':'abstract','retmode':'text'},timeout=25)
  print('ABSTRACTS',t.status_code,t.text[:7000])
